ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status) {
    ACPI_PARSE_OBJECT *ScopeOp;
    ACPI_PARSE_OBJECT *PrevOp;

    /* Check if we have an operation to complete */
    if (!Op) {
        return (Status);
    }

    /* Get the scope operation at the current scope level */
    ScopeOp = WalkState->ParserState.Scope[WalkState->ParserState.ScopeDepth - 1];

    /* If the current Op matches the scope Op, we are done with this scope */
    if (Op == ScopeOp) {
        WalkState->ParserState.ScopeDepth--;

        /* Check for ascending callbacks */
        if (WalkState->MethodNode && WalkState->MethodNode->Op && WalkState->MethodNode->Op == ScopeOp) {
            WalkState->MethodNode->Op = NULL;
        }
    }

    PrevOp = Op->Common.Next;
    Op->Common.Next = NULL;

    if (PrevOp) {
        PrevOp->Common.Parent = Op->Common.Parent;
    }

    return (Status);
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_STATUS Status2;
    ACPI_PARSE_OBJECT *PrevOp;

    /* Check if we need to handle ascending callbacks */
    if (WalkState->DescendingCallback && !WalkState->AscendingCallback) {
        WalkState->AscendingCallback = WalkState->DescendingCallback;
        WalkState->DescendingCallback = NULL;
    }

    /* Process the final operation and update the scope stack */
    PrevOp = Op->Common.Parent;
    if (PrevOp && PrevOp->Named.Name) {
        Status2 = AcpiPsCompleteThisOp(WalkState, Op);
        if (ACPI_FAILURE(Status2) && ACPI_SUCCESS(Status)) {
            Status = Status2;
        }

        /* Clear the scope stack if this is the last operation */
        if (!Op->Common.Child) {
            Status2 = AcpiUtPopScope(WalkState);
            if (ACPI_FAILURE(Status2) && ACPI_SUCCESS(Status)) {
                Status = Status2;
            }
        }
    }

    return Status;
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status) {
    ACPI_STATUS Status2;

    if (WalkState->ScopeDepth > 0) {
        WalkState->ScopeDepth--;
    }

    if (Op && Op->Asl.AscendingCallback) {
        Status2 = Op->Asl.AscendingCallback(WalkState, Op, Status);
        if (ACPI_FAILURE(Status2)) {
            return Status2;
        }
    }

    if (WalkState->ScopeDepth <= 0) {
        WalkState->Scope = NULL;
    }

    return Status;
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_STATUS Status2;

    if (WalkState->ScopeDepth > 0) {
        WalkState->ScopeDepth--;
    }

    if (WalkState->ScopeDepth == 0) {
        if (WalkState->Control) {
            ACPI_FREE(WalkState->Control);
        }

        WalkState->Control = NULL;
    }

    if (Status != AE_OK) {
        return Status;
    }

    if (Op->Asl.Value.ArgList) {
        Status2 = AcpiPsCompleteFinalOp(WalkState, Op->Asl.Value.ArgList, Status);
        if (Status2 != AE_OK) {
            return Status2;
        }
    }

    return AE_OK;
}

ACPI_STATUS AcpiPsCompleteOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *PrevOp;

    /* Check if there is a parent op and update its child link */
    if (Op->Common.Parent) {
        if (Op->Common.Parent->Value.ArgListNext) {
            Op->Common.Parent->Value.ArgListNext = Op->Common.Next;
        }
    }

    /* Execute ascending callbacks if any */
    if (WalkState->DescBasePtr && Op->Asl.Value.AmlOffset) {
        if (WalkState->ParserState.ScopeDepth > 0) {
            PrevOp = WalkState->ParserState.Scope[WalkState->ParserState.ScopeDepth - 1];
            WalkState->ParserState.Scope[WalkState->ParserState.ScopeDepth - 1] = Op;
            if (WalkState->ParserState.ScopeDepth > 1) {
                WalkState->ParserState.ScopeDepth--;
            }
        }

        if (WalkState->DescBasePtr) {
            (WalkState->DescBasePtr)(WalkState, Op, Status);
        }
    }

    /* Clear the scope stack if necessary */
    if (WalkState->ParserState.ScopeDepth > 0) {
        WalkState->ParserState.ScopeDepth--;
        if (WalkState->ParserState.ScopeDepth > 0) {
            WalkState->ParserState.Scope[WalkState->ParserState.ScopeDepth - 1] = NULL;
        }
    }

    return Status;
}
